INSERT INTO kakheti_heritage (category, title, description, fun_fact, image_url, location_name)
VALUES
-- კატეგორია: ისტორია (10)
('ისტორია', 'გრემის მთავარანგელოზთა კომპლექსი', 'XVI საუკუნის ეს დიდებული ციხე-სიმაგრე კახეთის სამეფოს დედაქალაქი იყო. დღეს ის რეგიონის ერთ-ერთი ყველაზე შთამბეჭდავი ვიზუალური სიმბოლოა.', 'იცოდით, რომ გრემი ერთ დროს აბრეშუმის გზის მნიშვნელოვანი სავაჭრო ჰაბი იყო და მას საკუთარი წყალმომარაგების სისტემა ჰქონდა?', 'https://images.unsplash.com/photo-1590272456521-1bbe160a18ce', 'გრემი'),
('ისტორია', 'ალავერდის მონასტერი', 'XI საუკუნის ხუროთმოძღვრების ძეგლი, რომელიც საუკუნეების განმავლობაში საქართველოში ყველაზე მაღალ ნაგებობად ითვლებოდა.', 'იცოდით, რომ ალავერდი საქართველოში ერთ-ერთი უძველესი საგანმანათლებლო ცენტრი იყო და აქ ხელნაწერთა გადაწერა ხდებოდა?', 'https://images.unsplash.com/photo-1628150490581-22878415712e', 'ალავერდი'),
('ისტორია', 'სიღნაღის ციხე-გალავანი', 'XVIII საუკუნეში ერეკლე II-ის მიერ აშენებული გალავანი, რომელსაც 23 კოშკი და 6 ჭიშკარი აქვს. ის ერთ-ერთი ყველაზე დიდია ევროპაში.', 'იცოდით, რომ სიღნაღის გალავნის თითოეულ კოშკს ახლომდებარე სოფლის სახელი ერქვა, რადგან ომის დროს სოფლის მოსახლეობა თავის კოშკს იცავდა?', 'https://images.unsplash.com/photo-1565620851603-467434151755', 'სიღნაღი'),
('ისტორია', 'ნეკრესის სამონასტრო კომპლექსი', 'კომპლექსი, რომელიც აერთიანებს სხვადასხვა ეპოქის ნაგებობებს. აქ მდებარეობს საქართველოში შემორჩენილი ერთ-ერთი უძველესი მცირე ბაზილიკა.', 'იცოდით, რომ ნეკრესის მონასტერი მთის წვერზეა გაშენებული და აქედან ალაზნის ველის ულამაზესი ხედი იშლება?', 'https://images.unsplash.com/photo-1632766329774-681534960337', 'ყვარელი'),
('ისტორია', 'იყალთოს აკადემია', 'XII საუკუნეში დაარსებული აკადემია, სადაც ასწავლიდნენ ფილოსოფიას, რიტორიკას, მჭედლობასა და მეღვინეობას.', 'იცოდით, რომ გადმოცემის თანახმად, იყალთოს აკადემიაში სწავლობდა დიდი ქართველი პოეტი შოთა რუსთაველი?', 'https://images.unsplash.com/photo-1610484826967-09c5720778c7', 'იყალთო'),
('ისტორია', 'უჯარმის ციხე', 'ადრეფეოდალური ხანის ციხე-ქალაქი, რომელიც ვახტანგ გორგასლის დროს ქვეყნის ერთ-ერთი უმნიშვნელოვანესი პოლიტიკური ცენტრი იყო.', 'იცოდით, რომ მეფე ვახტანგ გორგასალმა სიცოცხლის ბოლო წლები სწორედ უჯარმის ციხეში გაატარა?', 'https://images.unsplash.com/photo-1541432901042-2d8bd64b4a9b', 'უჯარმა'),
('ისტორია', 'ბოდბის მონასტერი', 'აქ განისვენებს წმინდა ნინო, ქართველთა განმანათლებელი. მონასტერი კახეთის უმთავრესი მომლოცველობითი ცენტრია.', 'იცოდით, რომ ბოდბის ტაძრის ქვემოთ მდებარეობს წმინდა ნინოს წყარო, რომელსაც ადგილობრივები სამკურნალო თვისებებს მიაწერენ?', 'https://images.unsplash.com/photo-1582042784795-364e0366624a', 'ბოდბე'),
('ისტორია', 'ხორნაბუჯის ციხე', 'კლდეზე გაშენებული მიუვალი ციხე-სიმაგრე, რომელსაც "თამარის ციხესაც" უწოდებენ. ის დედოფლისწყაროსთან მდებარეობს.', 'იცოდით, რომ ხორნაბუჯი იმდენად მაღალ კლდეზეა, რომ მასზე ასვლა ნამდვილი ალპინისტური თავგადასავალია?', 'https://images.unsplash.com/photo-1598453472097-f58694a961f5', 'დედოფლისწყარო'),
('ისტორია', 'ძველი და ახალი შუამთა', 'ორი სამონასტრო კომპლექსი, რომელიც ტყეშია ჩაფლული. ძველი შუამთა V-VII საუკუნეებისაა, ახალი კი XVI საუკუნის.', 'იცოდით, რომ ახალი შუამთა კახეთის დედოფალმა თინათინმა ააგო მას შემდეგ, რაც ხილვა ნახა, თუ სად უნდა აეშენებინა ტაძარი?', 'https://images.unsplash.com/photo-1610484826917-0f101a7bf7f4', 'თელავი'),
('ისტორია', 'ნინოწმინდის ტაძარი', 'VI საუკუნის ტაძარი, რომელიც ქართული ხუროთმოძღვრების განვითარების ერთ-ერთი უმნიშვნელოვანესი ეტაპია.', 'იცოდით, რომ ნინოწმინდის ტაძარი თავდაპირველად უზარმაზარი გუმბათოვანი ნაგებობა იყო, რომელიც მიწისძვრამ დააზიანა?', 'https://images.unsplash.com/photo-1635332219808-72b158580234', 'საგარეჯო'),

-- კატეგორია: ბუნება (10)
('ბუნება', 'ლაგოდეხის ჩანჩქერები', 'ნაკრძალის ტერიტორიაზე მდებარეობს "როჭოს" და "გურგენიანის" ულამაზესი ჩანჩქერები, რომლებიც ხელუხლებელ ბუნებაშია ჩაფლული.', 'იცოდით, რომ ლაგოდეხის ნაკრძალი საქართველოში პირველი დაცული ტერიტორიაა, რომელიც 1912 წელს დაარსდა?', 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e', 'ლაგოდეხი'),
('ბუნება', 'ვაშლოვანის ტალახის ვულკანები', 'უჩვეულო ლანდშაფტი დედოფლისწყაროსთან, რომელიც მარსის ზედაპირს მოგაგონებთ. აქ ტალახის პატარა კრატერები მუდმივად "დუღს".', 'იცოდით, რომ ვაშლოვანის ტალახის ვულკანებიდან ამოსული მასა სამკურნალო თვისებებისაა და კოსმეტოლოგიაშიც გამოიყენება?', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b', 'დედოფლისწყარო'),
('ბუნება', 'ლოპოტის ტბა', 'მთებს შორის მოქცეული ულამაზესი ტბა, რომელიც დასვენების საყვარელ ადგილად იქცა.', 'იცოდით, რომ ლოპოტას ტბის გარშემო არსებული მიკროკლიმატი განსაკუთრებით სასარგებლოა ჯანმრთელობისთვის?', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb', 'თელავი'),
('ბუნება', 'ყვარლის ტბა', 'მდინარე დურუჯის ხეობაში მდებარე ტბა, რომელიც გარშემორტყმულია საუკუნოვანი ტყეებით.', 'იცოდით, რომ ყვარლის ტბაზე ჩამოსული ნისლი ხშირად ქმნის მისტიკურ გარემოს, რაც ფოტოგრაფების საყვარელი სანახაობაა?', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470', 'ყვარელი'),
('ბუნება', 'არწივის ხეობა', 'კირქვიანი კლდეების ხეობა, სადაც იშვიათი ჯიშის მტაცებელი ფრინველები ბინადრობენ.', 'იცოდით, რომ არწივის ხეობაში შეგიძლიათ იხილოთ იშვიათი მცენარე - კახური მაჩიტა, რომელიც სხვაგან არსად იზრდება?', 'https://images.unsplash.com/photo-1472214103451-9374bd1c798e', 'დედოფლისწყარო'),
('ბუნება', 'ბაბანეურის ნაკრძალი', 'აქ დაცულია მესამეული პერიოდის რელიქტი - კავკასიური ძელქვა, რომელიც გადაშენების პირასაა.', 'იცოდით, რომ ძელქვა იმდენად მაგარი ხეა, რომ მას ძველად გემთმშენებლობაში იყენებდნენ?', 'https://images.unsplash.com/photo-1444021465936-c6ca81d39b84', 'ახმეტა'),
('ბუნება', 'ბაწარის ნაკრძალი', 'ადგილი, სადაც მსოფლიოში უნიკალური უთხოვრის ტყეა შემორჩენილი.', 'იცოდით, რომ უთხოვარი ძალიან ნელა იზრდება და ზოგიერთი ხე 1500 წელზე მეტი ხნისაა?', 'https://images.unsplash.com/photo-1473448912268-2022ce9509d8', 'ახმეტა'),
('ბუნება', 'ალაზნის ველი', 'საქართველოს ყველაზე დიდი ვაკე, რომელიც კავკასიონსა და გომბორის ქედს შორისაა გადაჭიმული.', 'იცოდით, რომ ალაზნის ველს კოსმოსიდანაც კარგად ჩანს მისი გეომეტრიული სიზუსტით დაყოფილი ვენახები?', 'https://images.unsplash.com/photo-1470770841072-f978cf4d019e', 'კახეთი'),
('ბუნება', 'გომბორის უღელტეხილი', 'თელავისა და თბილისის დამაკავშირებელი გზა, რომელიც ყველა სეზონზე განსხვავებული ფერებით გამოირჩევა.', 'იცოდით, რომ შემოდგომაზე გომბორზე მგზავრობა "ფერების ფესტივალს" ჰგავს მისი მრავალფეროვანი ფოთლოვანი ტყეების გამო?', 'https://images.unsplash.com/photo-1469474968028-56623f02e42e', 'საგარეჯო-თელავი'),
('ბუნება', 'ელიას მთა', 'დედოფლისწყაროს თავზე აღმართული მთა, სადაც წმინდა ელიას სახელობის ეკლესია კლდეშია ჩაშენებული.', 'იცოდით, რომ ალექსანდრე დიუმამ ელიას მთას "კავკასიის მთა-სიმაგრე" უწოდა?', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b', 'დედოფლისწყარო'),

-- კატეგორია: ღვინის კულტურა (10)
('ღვინის კულტურა', 'ქვევრის დამზადების ტრადიცია', 'კახური მეღვინეობის საფუძველი ქვევრია. სოფელ ვარდისუბანში დღემდე ცხოვრობენ მექვევრეები, რომლებიც ამ ხელობას თაობიდან თაობას გადასცემენ.', 'იცოდით, რომ იუნესკომ ქვევრის ღვინის დაყენების მეთოდს არამატერიალური კულტურული მემკვიდრეობის სტატუსი მიანიჭა?', 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3', 'ვარდისუბანი'),
('ღვინის კულტურა', 'რქაწითელი - კახეთის ოქრო', 'თეთრი ყურძნის ჯიში, რომელიც კახეთში ყველაზე მეტადაა გავრცელებული და მისგან საუკეთესო ქვევრის ღვინო დგება.', 'იცოდით, რომ რქაწითელი ერთ-ერთი უძველესი ჯიშია მსოფლიოში და მისი წიპწები ნეოლითის ხანის ნამოსახლარებშია ნაპოვნი?', 'https://images.unsplash.com/photo-1506377247377-2a5b3b0ca7ef', 'ალაზნის ველი'),
('ღვინის კულტურა', 'საფერავი - ქართული სიამაყე', 'წითელი ყურძნის ჯიში, რომელსაც "თვითმღებავს" უწოდებენ, რადგან მისი რბილობიც კი შეფერილია.', 'იცოდით, რომ საფერავი ერთ-ერთია იმ მცირერიცხოვან ჯიშებს შორის, რომლისგანაც ექსტრემალურად მუქი, თითქმის შავი ღვინო მიიღება?', 'https://images.unsplash.com/photo-1547595628-c61a29f496f0', 'კახეთი'),
('ღვინის კულტურა', 'რთველი კახეთში', 'ყურძნის მოსავლის აღების დღესასწაული, რომელიც ოჯახების გაერთიანების, სიმღერისა და სიხარულის სიმბოლოა.', 'იცოდით, რომ რთველი მხოლოდ სამუშაო პროცესი არაა? მას თან ახლავს "რთვლის სუფრა" და მრავალხმიანი კახური მრავალჟამიერი.', 'https://images.unsplash.com/photo-1523363344606-5387b3f9b2d8', 'კახეთი'),
('ღვინის კულტურა', 'ქინძმარაულის მიკროზონა', 'ადგილი ყვარელში, სადაც მდინარე დურუჯის ნალექები ქმნის უნიკალურ ნიადაგს ბუნებრივად ნახევრადტკბილი ღვინისთვის.', 'იცოდით, რომ ნამდვილი ქინძმარაული მხოლოდ ამ პატარა მიკროზონაში მოწეული ყურძნიდან შეიძლება დამზადდეს?', 'https://images.unsplash.com/photo-1516594915697-87eb3b1c14ea', 'ყვარელი'),
('ღვინის კულტურა', 'თამადის ინსტიტუტი', 'ქართული სუფრის წინამძღოლი, რომელიც სუფრას განსაზღვრული წესებითა და სადღეგრძელოებით მართავს.', 'იცოდით, რომ კახური სუფრა თამადის გარეშე წარმოუდგენელია და საუკეთესო თამადად ის ითვლება, ვისაც ბევრი სიმღერა და ლექსი იცის?', 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3', 'კახეთი'),
('ღვინის კულტურა', 'ჩურჩხელა - კახური ნუგბარი', 'ბადაგისა და ნიგვზისგან (ან თხილისგან) დამზადებული ტკბილეული, რომელსაც "ქართულ სნიკერსსაც" უწოდებენ.', 'იცოდით, რომ ძველად ქართველი მეომრები ომში ჩურჩხელას მიჰქონდათ, რადგან ის ძალიან ნოყიერია და დიდხანს ინახება?', 'https://images.unsplash.com/photo-1582281227059-74e69ca84333', 'კახეთი'),
('ღვინის კულტურა', 'ღვინის გვირაბი ყვარელში', 'კლდეში ნაკვეთი 7.7 კილომეტრიანი გვირაბი, სადაც ღვინის შესანახად იდეალური ბუნებრივი ტემპერატურაა.', 'იცოდით, რომ ეს გვირაბი თავდაპირველად სამხედრო დანიშნულების იყო და მოგვიანებით გადაკეთდა ღვინის საცავად?', 'https://images.unsplash.com/photo-1560493676-04071c5f467b', 'ყვარელი'),
('ღვინის კულტურა', 'ალექსანდრე ჭავჭავაძის მარანი', 'წინანდლის მამულში მდებარე მარანი, სადაც ინახება XIX საუკუნის უნიკალური ღვინოების კოლექცია (ენოთეკა).', 'იცოდით, რომ სწორედ წინანდალში ჩამოისხა პირველად ევროპული წესით დამზადებული ქართული ღვინო ბოთლებში?', 'https://images.unsplash.com/photo-1516594798947-e65505dbb29d', 'წინანდალი'),
('ღვინის კულტურა', 'კახური ქვევრი - მიწისქვეშა საიდუმლო', 'თიხის უზარმაზარი ჭურჭელი, რომელიც მიწაშია ჩაფლული და ღვინის დუღილისთვის სტაბილურ ტემპერატურას უზრუნველყოფს.', 'იცოდით, რომ ქვევრში ღვინო ჭაჭაზე (კანსა და კლერტზე) ვარგდება, რაც მას განსაკუთრებულ ქარვისფერ ფერსა და ტანინებს სძენს?', 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3', 'კახეთი'),

-- კატეგორია: ცნობილი ადამიანები (10)
('ცნობილი ადამიანები', 'მეფე ერეკლე II', 'კახეთის ლეგენდარული მეფე, "პატარა კახი", რომელიც მთელი ცხოვრება ბრძოლებში გაატარა ქვეყნის გადასარჩენად.', 'იცოდით, რომ ერეკლე II-მ 80-მდე დიდი და მცირე ბრძოლა გადაიხადა და თითქმის ყოველთვის გამარჯვებული გამოდიოდა?', 'https://images.unsplash.com/photo-1580618672591-eb180b1a973f', 'თელავი'),
('ცნობილი ადამიანები', 'ნიკო ფიროსმანი', 'გენიალური თვითნასწავლი მხატვარი მირზაანიდან, რომლის ნახატებმაც მსოფლიო აღიარება მოიპოვა.', 'იცოდით, რომ ფიროსმანის ცნობილი ისტორია "მილიონი ვარდის" შესახებ ნამდვილ ამბავს ეფუძნება, რომელიც მას ფრანგი მსახიობის მიმართ ჰქონდა?', 'https://images.unsplash.com/photo-1579783902614-a3fb3927b6a5', 'მირზაანი'),
('ცნობილი ადამიანები', 'ალექსანდრე ჭავჭავაძე', 'პოეტი, გენერალი და საზოგადო მოღვაწე, რომელმაც წინანდლის მამული კულტურული ცენტრად აქცია.', 'იცოდით, რომ ალექსანდრე ჭავჭავაძემ პირველმა შემოიტანა საქართველოში ფორტეპიანო და ევროპული ეტლი?', 'https://images.unsplash.com/photo-1505664194779-8beaceb93744', 'წინანდალი'),
('ცნობილი ადამიანები', 'ვაჟა-ფშაველა', 'მართალია ფშაველი იყო, მაგრამ მისი ცხოვრება და მოღვაწეობა მჭიდროდ იყო დაკავშირებული თელავის სემინარიასთან.', 'იცოდით, რომ ვაჟა-ფშაველა თელავში სწავლისას გამოირჩეოდა თავისი განსაკუთრებული ნიჭითა და თავისუფლებისმოყვარეობით?', 'https://images.unsplash.com/photo-1490750967868-88aa4486c946', 'თელავი'),
('ცნობილი ადამიანები', 'ქაქუცა ჩოლოყაშვილი', 'საქართველოს ეროვნული გმირი, რომელიც 1920-იან წლებში სათავეში ედგა პარტიზანულ მოძრაობას საბჭოთა რეჟიმის წინააღმდეგ.', 'იცოდით, რომ ქაქუცა ჩოლოყაშვილის რაზმს "შეფიცულები" ერქვათ და მათი სიმამაცე ლეგენდარული იყო?', 'https://images.unsplash.com/photo-1582281227059-74e69ca84333', 'ახმეტა'),
('ცნობილი ადამიანები', 'წმინდა ქეთევან დედოფალი', 'კახეთის დედოფალი, რომელმაც რწმენისთვის მოწამეობრივი სიკვდილი არჩია შირაზში.', 'იცოდით, რომ ქეთევან დედოფლის ნაწილები ინდოეთში, გოას მონასტერში იყო დაცული და მოგვიანებით საქართველოში გადმოასვენეს?', 'https://images.unsplash.com/photo-1582042784795-364e0366624a', 'კახეთი'),
('ცნობილი ადამიანები', 'იაკობ გოგებაშვილი', 'დიდი ქართველი პედაგოგი და "დედაენის" ავტორი, რომელიც განათლების სისტემის რეფორმატორი იყო.', 'იცოდით, რომ იაკობ გოგებაშვილის მიერ შედგენილი "დედაენა" დღემდე რჩება მთავარ სახელმძღვანელოდ პირველკლასელთათვის?', 'https://images.unsplash.com/photo-1456513080510-7bf3a84b82f8', 'კახეთი'),
('ცნობილი ადამიანები', 'მეფე თეიმურაზ I', 'კახეთის ტრაგიკული ბედის მეფე და პოეტი, რომელიც თავადვე აღწერდა თავისი ქვეყნის უბედურებას ლექსებში.', 'იცოდით, რომ თეიმურაზ I-ს ეკუთვნის ცნობილი პოემა "ვარდბულბულიანი", რომელიც სპარსული პოეზიის გავლენითაა დაწერილი?', 'https://images.unsplash.com/photo-1544642239-6b55bd3a3e68', 'კახეთი'),
('ცნობილი ადამიანები', 'ვანო სარაჯიშვილი', 'ლეგენდარული მომღერალი, "საქართველოს ბულბული", რომლის ხმამაც მთელი მსოფლიო აღაფრთოვანა.', 'იცოდით, რომ ვანო სარაჯიშვილის ხმის მოსასმენად ხალხი საოპერო თეატრთან საათობით რიგში იდგა?', 'https://images.unsplash.com/photo-1511379938547-c1f69419868d', 'სიღნაღი'),
('ცნობილი ადამიანები', 'ბიძინა ჩოლოყაშვილი', 'კახეთის აჯანყების ერთ-ერთი სულისჩამდგმელი (1659 წ.), რომელმაც თავი გასწირა სამშობლოსთვის.', 'იცოდით, რომ ბიძინა ჩოლოყაშვილი შალვა და ელიზბარ ქსნის ერისთავებთან ერთად წმინდანადაა შერაცხული?', 'https://images.unsplash.com/photo-1580618672591-eb180b1a973f', 'ახმეტა'),

-- კატეგორია: ლეგენდები (10)
('ლეგენდები', 'სიღნაღი - სიყვარულის ქალაქი', 'ლეგენდა ამბობს, რომ სიღნაღში ნებისმიერ დროს შეგიძლიათ დაქორწინება და აქაური ჰაერი სიყვარულითაა გაჟღენთილი.', 'იცოდით, რომ სიღნაღში ქორწინების სახლი 24 საათის განმავლობაში მუშაობს და ნებისმიერ მსურველს იღებს?', 'https://images.unsplash.com/photo-1565620851603-467434151755', 'სიღნაღი'),
('ლეგენდები', 'ალავერდის დაარსება', 'გადმოცემით, ტაძრის ადგილას ადრე უდაბნო იყო, სანამ მხოლოდ იოსებ ალავერდელი მოღვაწეობდა, სანამ ხალხმა აქ ტაძარი არ ააგო.', 'იცოდით, რომ "ალავერდი" თურქული წარმოშობისაა და ნიშნავს "ღმერთმა მისცა"?', 'https://images.unsplash.com/photo-1628150490581-22878415712e', 'ალავერდი'),
('ლეგენდები', 'ვაზის ლეგენდა', 'ლეგენდის თანახმად, ქართველმა მეომარმა მკერდზე ვაზის ლერწი დაიმაგრა, რომ თუ ბრძოლაში დაეცემოდა, მის სხეულზე ვაზი აღმოცენებულიყო.', 'იცოდით, რომ ეს ლეგენდა დღემდე ითვლება ქართველი კაცისა და ვაზის განუყოფელი კავშირის სიმბოლოდ?', 'https://images.unsplash.com/photo-1506377247377-2a5b3b0ca7ef', 'კახეთი'),
('ლეგენდები', 'გრემის ციხის აჩრდილი', 'ადგილობრივები ჰყვებიან ლეგენდას გრემის ციხის საიდუმლო გვირაბებსა და იქ მობინადრე აჩრდილებზე, რომლებიც განძს იცავენ.', 'იცოდით, რომ გრემის ციხეს მართლაც აქვს საიდუმლო გვირაბი, რომელიც მდინარისკენ ჩადის?', 'https://images.unsplash.com/photo-1590272456521-1bbe160a18ce', 'გრემი'),
('ლეგენდები', 'თელავის გიგანტური ჭადარი', 'ლეგენდა ამბობს, რომ ეს 900 წლის ხე ქალაქის მფარველია და სანამ ის ცოცხალია, თელავი იარსებებს.', 'იცოდით, რომ ამ ხესთან ფოტო აქვს გადაღებული თითქმის ყველა ცნობილ ადამიანს, ვინც კი თელავში ჩასულა?', 'https://images.unsplash.com/photo-1544148103-0773bf10d330', 'თელავი'),
('ლეგენდები', 'წმინდა ნინო და ბოდბე', 'ლეგენდის თანახმად, წმინდა ნინომ ბოდბეში სიკვდილის წინ ილოცა და იმ ადგილას წყარო ამოხეთქა.', 'იცოდით, რომ ბოდბის წყაროში განბანვის შემდეგ, გადმოცემით, უამრავი ადამიანი განიკურნა?', 'https://images.unsplash.com/photo-1582042784795-364e0366624a', 'ბოდბე'),
('ლეგენდები', 'ხორნაბუჯის "არწივის ბუდე"', 'ამბობენ, რომ ხორნაბუჯის ციხეზე მხოლოდ არწივებს შეეძლოთ ბუდობის გაკეთება, სანამ მეფეებმა ის ციხე-სიმაგრედ არ აქციეს.', 'იცოდით, რომ ხორნაბუჯის ციხე იმდენად მაღალია, რომ ხშირად ღრუბლები მის ქვემოთ მოჩანს?', 'https://images.unsplash.com/photo-1598453472097-f58694a961f5', 'დედოფლისწყარო'),
('ლეგენდები', 'კახური სტუმართმოყვარეობა', 'ლეგენდა ამბობს, რომ კახეთში სტუმარი ღვთისაა და თუ კარს ვინმე მოგიკაკუნებს, მას საუკეთესო ღვინო და პური უნდა მიართვა.', 'იცოდით, რომ კახეთში არსებობს ტრადიცია, რომლის მიხედვითაც სტუმრისთვის სპეციალურად ინახავენ საუკეთესო ქვევრს?', 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3', 'კახეთი'),
('ლეგენდები', 'ყინულიანი დურუჯი', 'ყვარელში ჰყვებიან, რომ მდინარე დურუჯს შეუძლია უზარმაზარი ლოდების მოტანა და ამიტომ მას განსაკუთრებული პატივისცემით ეპყრობიან.', 'იცოდით, რომ დურუჯის მიერ მოტანილმა ნალექებმა შექმნა ის უნიკალური ნიადაგი, რაზეც ქინძმარაული იზრდება?', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470', 'ყვარელი'),
('ლეგენდები', 'გომბორის ტყის ფერიები', 'ძველი გადმოცემით, გომბორის უღელტეხილზე ნისლიან ამინდში ტყის ფერიები გამოდიან და მგზავრებს გზას უბნევენ.', 'იცოდით, რომ ეს ლეგენდა ხშირად გამოიყენებოდა იმისთვის, რომ ბავშვები ტყეში მარტო არ შესულიყვნენ?', 'https://images.unsplash.com/photo-1444021465936-c6ca81d39b84', 'გომბორი');